	@Test
	@EnabledIfSystemProperty(named = "spill.sizeRegression", matches = "true")
	void currentModelSizeAfterMutationIsExact() throws Exception {
		Path output = freshDirectory("size-regression-current");
		DynamicModel input = inputModel(new AtomicInteger());
		for (int i = 0; i < 9_001; i++) {
			input.add(row(i, true, true));
		}
		try (LmdbSailStore store = newStore(output.resolve("native"))) {
			SailSourceModel model = new SailSourceModel(store, input);
			try {
				assertTrue(model.clear(VF.createIRI("urn:spill:context:0")));
				assertTrue(model.add(row(0, true, true)));
				assertTrue(model.contains(row(0, true, true)));
				verifyRows(store, 9_001, true, true);
				assertEquals(9_001, model.size());
			} finally {
				closeModel(model);
			}
		}
	}

	@Test
	void streamingConstructorPreservesDataAndMutations() throws Exception {
		Path output = freshDirectory("semantics");
		AtomicInteger upgrades = new AtomicInteger();
		DynamicModel input = inputModel(upgrades);
		for (int i = 0; i < 9_001; i++) {
			input.add(row(i, true, true));
		}
		IRI largeSubject = VF.createIRI("urn:spill:large");
		Literal largeValue = VF.createLiteral("large-value-".repeat(10_000), "en");
		Resource blankContext = VF.createBNode("spill-blank-context");
		Statement largeStatement = VF.createStatement(largeSubject, PREDICATE, largeValue, blankContext);
		assertTrue(input.add(largeStatement));
		assertFalse(input.add(largeStatement));
		Statement defaultStatement = VF.createStatement(VF.createIRI("urn:spill:default"), PREDICATE,
				VF.createLiteral(42));
		assertTrue(input.add(defaultStatement));
		input.setNamespace("spill", "urn:spill:");
		try (LmdbSailStore store = newStore(output.resolve("native"))) {
			StreamingSpillPrototypeModel model = new StreamingSpillPrototypeModel(store, input);
			try {
				assertEquals(0, upgrades.get(), "Streaming must not request the indexed DynamicModel representation");
				assertEquals(input.size(), model.size());
				assertEquals("urn:spill:", model.getNamespace("spill").orElseThrow().getName());
				for (Statement statement : input) {
					assertTrue(model.contains(statement), statement.toString());
				}
				assertFalse(model.add(largeStatement));
				assertTrue(model.remove(largeStatement));
				assertFalse(model.contains(largeStatement));
				assertTrue(model.add(largeStatement));
				assertTrue(model.contains(largeStatement));
				assertTrue(model.clear(blankContext));
				assertFalse(model.contains(largeStatement));
				assertTrue(model.contains(defaultStatement));
				assertTrue(model.clear((Resource) null));
				assertFalse(model.contains(defaultStatement));
				for (int i = 0; i < 9_001; i++) {
					assertTrue(model.contains(row(i, true, true)), "preserved row " + i);
				}
				assertEquals(9_001, countStatements(model));
				model.setNamespace("other", "urn:other:");
				assertEquals("urn:other:", model.getNamespace("other").orElseThrow().getName());
				assertEquals("urn:other:", model.removeNamespace("other").orElseThrow().getName());
				model.clear();
				assertEquals(0, countStatements(model));
			} finally {
				closeModel(model);
			}
		}
	}

	private static DynamicModel inputModel(AtomicInteger upgrades) {
		return new DynamicModel(() -> {
			upgrades.incrementAndGet();
			return new LinkedHashModel();
		});
	}

	private static Statement row(int index, boolean highContexts, boolean highPredicates) {
		IRI subject = VF.createIRI(SUBJECT_PREFIX + index);
		IRI predicate = highPredicates ? VF.createIRI("urn:spill:predicate:" + index) : PREDICATE;
		Resource context = highContexts ? VF.createIRI("urn:spill:context:" + index) : SHARED_CONTEXT;
		return VF.createStatement(subject, predicate, VF.createLiteral(index), context);
	}

	private static int countStatements(StreamingSpillPrototypeModel model) {
		Iterator<Statement> statements = model.iterator();
		int count = 0;
		try {
			while (statements.hasNext()) {
				statements.next();
				count++;
			}
		} finally {
			model.closeIterator(statements);
		}
		return count;
	}

	private static void verifyRows(LmdbSailStore store, int rows, boolean highContexts, boolean highPredicates) {
		BitSet seen = new BitSet(rows);
		int count = 0;
		try (SailDataset dataset = store.getExplicitSailSource().dataset(IsolationLevels.NONE);
				CloseableIteration<? extends Statement> statements = dataset.getStatements(null, null, null)) {
			while (statements.hasNext()) {
				Statement actual = statements.next();
				int index = Integer.parseInt(actual.getSubject().stringValue().substring(SUBJECT_PREFIX.length()));
				assertTrue(index >= 0 && index < rows);
				assertFalse(seen.get(index), "Duplicate native statement");
				assertEquals(row(index, highContexts, highPredicates), actual);
				seen.set(index);
				count++;
			}
		}
		assertEquals(rows, count);
		assertEquals(rows, seen.cardinality());
	}

	private static LmdbSailStore newStore(Path directory) throws IOException {
		Files.createDirectories(directory);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc")
				.setTripleDBSize(512L * 1024 * 1024)
				.setValueDBSize(512L * 1024 * 1024)
				.setForceSync(false);
		LmdbSailStore store = new LmdbSailStore(directory.toFile(), new StoreProperties(), config, false);
		store.enableMultiThreading = false;
		return store;
	}

	private static Path freshDirectory(String suffix) throws IOException {
		String root = System.getProperty("spill.output", "work/lmdb-growth-spill-20261007/spill");
		Path parent = Path.of(root).toAbsolutePath();
		Files.createDirectories(parent);
		return Files.createTempDirectory(parent, suffix + "-");
	}

	private static long nativeBytes(Path directory) throws IOException {
		try (var paths = Files.walk(directory)) {
			long bytes = 0;
			for (Path path : paths.filter(Files::isRegularFile).toList()) {
				bytes += Files.size(path);
			}
			return bytes;
		}
	}

	private static void closeModel(AbstractModel model) {
		if (model instanceof SailSourceModel source) {
			if (source.dataset != null) {
				source.dataset.close();
			}
			if (source.sink != null) {
				source.sink.close();
			}
		} else if (model instanceof StreamingSpillPrototypeModel source) {
			if (source.dataset != null) {
				source.dataset.close();
			}
			if (source.sink != null) {
				source.sink.close();
			}
		}
	}

	private static long heapUsed() {
		return Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
	}

	private static final class HeapSampler implements AutoCloseable {
		private final AtomicLong peak;
		private volatile boolean running = true;
		private final Thread thread;

		HeapSampler(long baseline) {
			peak = new AtomicLong(baseline);
			thread = Thread.ofPlatform().daemon().name("spill-heap-sampler").start(() -> {
				while (running) {
					peak.accumulateAndGet(heapUsed(), Math::max);
					LockSupport.parkNanos(2_000_000L);
				}
			});
		}

		long peak() {
			return peak.get();
		}

		@Override
		public void close() throws InterruptedException {
			running = false;
			thread.join();
		}
	}
